INSERT INTO `sys_history` (`uid`, `tstamp`, `actiontype`, `usertype`, `userid`, `originaluserid`, `recuid`, `tablename`, `history_data`, `workspace`, `correlation_id`) VALUES
(754, 1740991888, 2, 'BE', 2, 0, 19, 'tx_news_domain_model_news', '{\"oldRecord\":{\"bodytext\":\"<p>Am vergangenen Wochenende verwandelte sich die Feuerwehr Gammelsdorf kurzzeitig in eine Faschingshochburg. Mit einem abwechslungsreichen Programm, das von Tanz, Musik und ausgelassener Stimmung gepr\\u00e4gt war, begeisterten die Akteure das Publikum.<\\/p>\\r\\n<p>Den Auftakt machte die Showgruppe der Feuerwehr, die mit ihrer energiegeladenen Darbietung gleich zu Beginn f\\u00fcr beste Stimmung sorgte. Anschlie\\u00dfend \\u00fcbernahm der Jugendhofstaat der Narrhalla Gammelsdorf die B\\u00fchne. Die Kinderelfer leiteten den Auftritt ein, gefolgt von der bezaubernden Kindergarde, die mit beeindruckenden Choreografien begeisterte. Danach sorgte die Kindershow f\\u00fcr einen weiteren H\\u00f6hepunkt, der die jungen Narren zum Mitmachen animierte.<\\/p>\\r\\n<p>Eine kurze Unterbrechung durch einen Einsatz der Feuerwehr brachte einen Moment der Spannung, doch die Veranstaltung wurde schnell wieder fortgesetzt. Den kr\\u00f6nenden Abschluss der Narrhalla-Jugend bildete die Gruppe \\\"Young Revolution\\\" mit ihrer mitrei\\u00dfenden Show, die das Publikum noch einmal zum Staunen brachte.<\\/p>\\r\\n<p>Als besonderes Highlight des Abends traten die Exprinzessinnen auf, die als Special Guests eine spektakul\\u00e4re Show darboten. Ihr Auftritt rundete das Programm perfekt ab und sorgte f\\u00fcr einen geb\\u00fchrenden Abschluss des gelungenen Faschingstreibens.<\\/p>\\r\\n<p>F\\u00fcr das leibliche Wohl war ebenfalls bestens gesorgt \\u2013 die Feuerwehr Gammelsdorf versorgte die G\\u00e4ste mit Speisen und Getr\\u00e4nken, sodass es an nichts fehlte.<\\/p>\\r\\n<p>Die Feuerwehr Gammelsdorf hat einmal mehr bewiesen, dass sie nicht nur im Ernstfall zur Stelle ist, sondern auch eine herausragende Gastgeberin f\\u00fcr fr\\u00f6hliche und kurzweilige Veranstaltungen ist. Wir freuen uns bereits auf n\\u00e4chstes Jahr.&nbsp;<\\/p>\"},\"newRecord\":{\"bodytext\":\"<p>Am vergangenen Wochenende verwandelte sich die Feuerwehr Gammelsdorf kurzzeitig in eine Faschingshochburg. Mit einem abwechslungsreichen Programm, das von Tanz, Musik und ausgelassener Stimmung gepr\\u00e4gt war, begeisterten die Akteure das Publikum.<\\/p>\\r\\n<p>Den Auftakt machte die Showgruppe der Feuerwehr, die mit ihrer energiegeladenen Darbietung gleich zu Beginn f\\u00fcr beste Stimmung sorgte. Anschlie\\u00dfend \\u00fcbernahm der Jugendhofstaat der Narrhalla Gammelsdorf die B\\u00fchne. Die Kinderelfer leiteten den Auftritt ein, gefolgt von der bezaubernden Kindergarde, die mit beeindruckenden Choreografien begeisterte. Danach sorgte die Kindershow f\\u00fcr einen weiteren H\\u00f6hepunkt, der die jungen Narren zum Mitmachen animierte.<\\/p>\\r\\n<p>Eine kurze Unterbrechung durch einen Einsatz der Feuerwehr (<a href=\\\"t3:\\/\\/page?uid=43#45\\\">siehe hier<\\/a>) brachte einen Moment der Spannung, doch die Veranstaltung wurde schnell wieder fortgesetzt. Den kr\\u00f6nenden Abschluss der Narrhalla-Jugend bildete die Gruppe \\\"Young Revolution\\\" mit ihrer mitrei\\u00dfenden Show, die das Publikum noch einmal zum Staunen brachte.<\\/p>\\r\\n<p>Als besonderes Highlight des Abends traten die Exprinzessinnen auf, die als Special Guests eine spektakul\\u00e4re Show darboten. Ihr Auftritt rundete das Programm perfekt ab und sorgte f\\u00fcr einen geb\\u00fchrenden Abschluss des gelungenen Faschingstreibens.<\\/p>\\r\\n<p>F\\u00fcr das leibliche Wohl war ebenfalls bestens gesorgt \\u2013 die Feuerwehr Gammelsdorf versorgte die G\\u00e4ste mit Speisen und Getr\\u00e4nken, sodass es an nichts fehlte.<\\/p>\\r\\n<p>Die Feuerwehr Gammelsdorf hat einmal mehr bewiesen, dass sie nicht nur im Ernstfall zur Stelle ist, sondern auch eine herausragende Gastgeberin f\\u00fcr fr\\u00f6hliche und kurzweilige Veranstaltungen ist. Wir freuen uns bereits auf n\\u00e4chstes Jahr.&nbsp;<\\/p>\"}}', 0, '0400$2adfff25b92318881785616afa6681b9:b3bb85e5f9734ca775c8443d6c623425'),
