(31, 38, 1740059420, 1738926728, 0, 0, 0, 0, '', 256, '', 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'none', 0, NULL, 0, 'news_newsdetail', 0, 0, '', '', 0, '', 0, '', '', '', NULL, 0, 0, 0, 0, 0, 0, 0, 2, NULL, 0, '', 0, NULL, 1, 0, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"settings.singleNews\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.previewHiddenRecords\">\n                    <value index=\"vDEF\">2</value>\n                </field>\n                <field index=\"settings.startingpoint\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.recursive\">\n                    <value index=\"vDEF\"></value>\n                </field>\n            </language>\n        </sheet>\n        <sheet index=\"additional\">\n            <language index=\"lDEF\">\n                <field index=\"settings.detailPid\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.backPid\">\n                    <value index=\"vDEF\">1</value>\n                </field>\n                <field index=\"settings.excludeAlreadyDisplayedNews\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n                <field index=\"settings.disableOverrideDemand\">\n                    <value index=\"vDEF\">1</value>\n                </field>\n            </language>\n        </sheet>\n        <sheet index=\"template\">\n            <language index=\"lDEF\">\n                <field index=\"settings.media.maxWidth\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.media.maxHeight\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.templateLayout\">\n                    <value index=\"vDEF\"></value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, '', 0, 0, 0, 0, 3, 2, 1),
(32, 39, 1739350670, 1739349471, 0, 0, 0, 0, '', 256, '', 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'textpic', 0, 0, '', '', 0, 'Mitglied werden', 0, '', '', 'Aktiver Feuerwehrdienst', '<p><strong>Das können wir Dir bieten:</strong></p>\r\n<ul><li>Eine hervorragende Ausbildung zum Feuerwehrmann bzw. zur Feuerwehrfrau durch Lehrgänge auf Gemeinde-, Kreis- und Landesebene</li><li>Eine spannende und abwechslungsreiche Tätigkeit</li><li>Viel Kameradschaft</li><li>Umgang mit moderner Technik und Fahrzeugen</li><li>Das gute Gefühl anderen Menschen helfen zu können</li><li>Bayerische Ehrenamtskarte, nach abgeschlossener Ausbildung</li></ul>\r\n<p><strong>Voraussetzungen:</strong></p>\r\n<ul><li>Du wohnst oder arbeitest in Gammelsdorf</li><li>Du bist zwischen 18 und 65 Jahren alt</li><li>Du nimmst regelmäßig an Dienstveranstaltungen teil</li><li>Du absolvierst die Ausbildung zum Feuerwehrmann beziehungsweise zur Feuerwehrfrau bildest dich auf Lehrgängen weiter</li><li>… um dann so oft und so schnell wie möglich nach der Alarmierung zu Einsätzen zu erscheinen&nbsp;</li></ul>\r\n\r\n\r\n', 1, 0, 0, 0, 18, 0, 1, 2, NULL, 0, '', 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, '', 0, 0, 0, 0, 3, 2, 1),
(33, 39, 1741385383, 1739350560, 0, 0, 0, 0, '', 512, '', 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'text', 0, 0, '', '', 0, '', 0, '', '', 'Du möchtest aktives Mitglied der Feuerwehr Gammelsdorf werden?', '<p>Dann komm einfach bei uns vorbei oder ruf uns an!<br />Unsere Kommandanten stehen dir jederzeit für Fragen zur Verfügung – gerne auch per E-Mail: <a rel=\"noopener\"><strong>kommandanten@feuerwehr-gammelsdorf.de</strong></a></p>\r\n<p>Außerdem bist du herzlich eingeladen, an einer unserer Übungsdienste teilzunehmen. Die aktuellen Termine findest du hier: <a href=\"t3://page?uid=13\" title=\"Kalender\">Kalender</a></p>\r\n<p>Den Mitgliedsantrag kannst du ganz einfach als PDF herunterladen, ausfüllen und uns zukommen lassen:<br />📌 Persönlich bei einem unserer Treffen<br />📌 Per Einwurf in den Briefkasten am Feuerwehrhaus (<i>Am Bachberg 4, 85408 Gammelsdorf</i>)</p>\r\n<p>Wir freuen uns auf dich! 🚒🔥</p>', 0, 0, 0, 0, 0, 0, 0, 2, NULL, 0, '', 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, '', 0, 0, 0, 0, 3, 2, 1),
(34, 39, 1739350715, 1739350701, 1, 0, 0, 0, '0', 384, NULL, 0, 0, 0, 0, NULL, '', 0, 0, 0, 0, 'default', 0, NULL, 0, 'div', 0, 0, '', '', 0, '', 0, '', '', '', NULL, 0, 0, 0, 0, 0, 0, 0, 2, NULL, 0, '', 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, '', 0, 0, 0, 0, 3, 2, 1);
